def _history(split, dt, threshold):
    h = np.asarray(split['past_stress'], dtype=float)
    s = np.asarray(split['stress_hold_0'], dtype=float)
    ov = np.sign(s) * np.maximum(np.abs(s) - threshold, 0.0) ** 2
    work = np.maximum(np.abs(h) - threshold, 0.0) ** 2 @ dt * s
    return (h, s, ov, work)

def _fit_memory(history, dt, t, train):
    from scipy.optimize import minimize
    y = np.column_stack((train['strain_curves_obs'] - train['strain_0'][:, None], train['instant_rate_obs']))
    scale = np.r_[np.full(len(t), 0.026), 0.016]
    b = np.r_[t, 1.0] / scale
    y = y / scale

    def profile(log_tau, full=False):
        A = _branches(history, dt, t, np.exp(log_tau)) / scale[None, :, None]
        w = np.ones_like(y)
        for _ in range(24):
            (coeff, drift, resid) = _project(A, y, b, w)
            new_w = 1.0 / (1.0 + resid ** 2)
            if np.max(np.abs(w - new_w)) < 1e-05:
                break
            w = new_w
        if full:
            return (coeff, drift)
        return np.mean(np.log1p(resid ** 2))
    bounds = [(np.log(0.2), np.log(8.0))] * 2
    ordered = {'type': 'ineq', 'fun': lambda u: u[1] - u[0] - 1e-06}
    fits = [minimize(profile, np.log(start), method='SLSQP', bounds=bounds, constraints=ordered, options={'ftol': 1e-10, 'maxiter': 70}) for start in ((0.45, 3.0), (1.0, 5.5))]
    log_tau = min(fits, key=lambda f: f.fun).x
    (coeff, drift) = profile(log_tau, full=True)
    return (np.exp(log_tau), coeff, drift)

def _fit_drift(x, ov, slopes):
    A = np.column_stack((np.ones(len(x)), x, ov))
    w = np.ones(len(x))
    for step in range(20):
        root = np.sqrt(w)
        coef = np.linalg.lstsq(A * root[:, None], slopes * root, rcond=None)[0]
        r = slopes - A @ coef
        if step == 0:
            scale = max(0.014, 1.4826 * np.median(np.abs(r - np.median(r))))
        w = 1.0 / (1.0 + (r / (2 * scale)) ** 2)
    return (coef, scale)
